// Bash command analysis on top of a real parser (vendored unbash), so rules see
// commands, not substrings: quoting, pipelines, subshells, $(...) and `...` are
// all handled by the parser.
import { parse } from './vendor/unbash/parser.js'

export interface SimpleCommand {
  name: string // basename of the program, wrappers (sudo, env, ...) removed
  prog: string // the program as written, path included (`/bin/ls`)
  args: string[] // its arguments, quotes removed
  wrappers: string[] // wrappers removed from in front of it (and of a shell running it), outermost first
  wrapped: string[][] // per wrapper, parallel to `wrappers`: that wrapper's whole invocation, options and wrapped command included
  captured: boolean // its stdout is consumed: left of a pipe, or inside $(...), `...` or <(...)
  redirects: Redirection[] // its own, then those of the compound commands and shells (`bash -c`) around it, innermost first
  stdout: string // where those redirects send its stdout: a file, `&N` for another descriptor, or '' if they don't
}

export interface Redirection {
  op: string // > >> >| < <> <& >& &> &>> << <<- <<<
  fd: number // the descriptor written before the operator, -1 if none, -2 for a {var} one
  target: string // the file, descriptor or here-string word; a heredoc's delimiter
  body: string // what a heredoc or here-string feeds to stdin; '' for the others
  quoted: boolean // a heredoc whose delimiter is quoted, so its body is not expanded
}

// Wrappers that run another command given as their first non-option argument.
// argOpts: short options that consume a following argument (`sudo -u root`).
// positionals: leading positionals owned by the wrapper (`timeout 5 cmd`).
const WRAPPERS: Record<string, { argOpts?: string; positionals?: number }> = {
  sudo: { argOpts: 'ugCDhprtUR' },
  doas: { argOpts: 'uC' },
  run0: { argOpts: 'ugD' },
  env: { argOpts: 'uCS' },
  command: {},
  builtin: {},
  exec: { argOpts: 'a' },
  nohup: {},
  time: { argOpts: 'fo' },
  nice: { argOpts: 'n' },
  ionice: { argOpts: 'cnp' },
  setsid: {},
  stdbuf: { argOpts: 'ioe' },
  timeout: { argOpts: 'ks', positionals: 1 },
  xargs: { argOpts: 'aEeIiLnPsd' },
}

// Shells whose `-c` argument is itself a script
const SHELLS = new Set(['bash', 'sh', 'zsh', 'dash', 'ksh'])

const MAX_DEPTH = 8

const basename = (p: string): string => p.slice(p.lastIndexOf('/') + 1)

const argText = (a: any): string => (a.type === 'Assignment' ? a.text : a.value)

function redirection(r: any): Redirection {
  const fd = typeof r.descriptor?.value === 'number' ? r.descriptor.value : r.descriptor ? -2 : -1
  if (r.type === 'HereDoc')
    return { op: r.operator, fd, target: r.delimiter?.value ?? '', body: r.body?.text ?? '', quoted: !!r.delimiter?.quoted }
  const target = r.target?.value ?? ''
  return { op: r.operator, fd, target, body: r.type === 'HereString' ? target + '\n' : '', quoted: false }
}

// Where one command's (or compound's) own redirects send stdout: the last that touches it wins
function stdoutOf(redirects: readonly Redirection[]): string {
  let out = ''
  for (const r of redirects) {
    if (r.op === '&>' || r.op === '&>>') out = r.target
    else if (r.fd !== -1 && r.fd !== 1) continue
    else if (r.op === '>' || r.op === '>>' || r.op === '>|') out = r.target
    // >&2 duplicates a descriptor; >&file is &>file
    else if (r.op === '>&') out = /^(\d+|-)$/.test(r.target) ? `&${r.target}` : r.target
  }
  return out
}

function unwrap(words: string[]): { words: string[]; wrappers: string[]; wrapped: string[][] } {
  const wrappers: string[] = []
  const wrapped: string[][] = []
  for (let guard = 0; words.length && guard < 16; guard++) {
    const prog = basename(words[0]!)
    const w = WRAPPERS[prog]
    if (!w) break
    wrappers.push(prog)
    wrapped.push(words)
    let i = 1
    let skip = w.positionals ?? 0
    for (; i < words.length; i++) {
      const t = words[i]!
      if (t === '--') {
        i++
        break
      }
      if (t.startsWith('-') && t.length > 1) {
        if (!t.startsWith('--') && t.length === 2 && w.argOpts?.includes(t[1]!)) i++
        continue
      }
      if (prog === 'env' && /^[A-Za-z_][A-Za-z0-9_]*=/.test(t)) continue
      if (skip > 0) {
        skip--
        continue
      }
      break
    }
    words = words.slice(i)
  }
  return { words, wrappers, wrapped }
}

// Every child of a node. The parser's lazy fields (parts, elements, index,
// expression, ...) are not own properties, but its toJSON() lists them all.
function children(node: any): any[] {
  return Object.values(typeof node.toJSON === 'function' ? node.toJSON() : node)
}

type Visit = (n: any, captured: boolean, outer: readonly Redirection[][]) => void

// `outer`: the redirects of each compound command around the node, innermost first
function walk(node: any, visit: Visit, captured = false, outer: readonly Redirection[][] = [], seen = new Set<any>()): void {
  if (!node || typeof node !== 'object' || seen.has(node)) return
  seen.add(node)
  if (Array.isArray(node)) {
    for (const n of node) walk(n, visit, captured, outer, seen)
    return
  }
  if (typeof node.type === 'string') visit(node, captured, outer)
  if (node.type === 'Pipeline') {
    // Every stage but the last feeds the next one, so its stdout is captured
    const last = node.commands.length - 1
    node.commands.forEach((c: any, i: number) => walk(c, visit, captured || i < last, outer, seen))
    return
  }
  // A substitution's output goes to the command around it, not to that command's redirects
  const expansion = node.type === 'CommandExpansion' || node.type === 'ProcessSubstitution'
  // $(...), `...` and <(...) hand the output to the surrounding command
  const inner = captured || node.type === 'CommandExpansion' || (node.type === 'ProcessSubstitution' && node.operator === '<')
  const redirs = expansion ? [] : node.type === 'Redirected' ? [node.redirects.map(redirection), ...outer] : outer
  for (const v of children(node)) walk(v, visit, inner, redirs, seen)
}

export interface Analysis {
  commands: SimpleCommand[]
  errors: string[] // parse errors, including those in nested scripts; empty if well-formed
  untilClauses: SimpleCommand[][] // per `until` / `while !` loop, the commands of its condition
  pipelines: SimpleCommand[][] // per pipeline, its stages in order; a stage that is not a simple command has name ''
}

/** Every simple command in `source`, including those nested in subshells,
 *  substitutions, control structures and `sh -c '...'` / `eval` strings, plus
 *  any parse errors. A non-empty `errors` means `commands` may be incomplete. */
export function analyze(source: string, depth = 0): Analysis {
  const out: Analysis = { commands: [], errors: [], untilClauses: [], pipelines: [] }
  if (depth > MAX_DEPTH) {
    out.errors.push('nesting too deep')
    return out
  }
  let ast: any
  try {
    ast = parse(source)
  } catch (err) {
    out.errors.push(String((err as Error)?.message ?? err))
    return out
  }
  // A nested script's commands inherit the shell's wrappers (`sudo sh -c ...`), capture and redirects
  const nested = (script: string, shell: SimpleCommand) => {
    const sub = analyze(script, depth + 1)
    const lift = new Map<SimpleCommand, SimpleCommand>()
    for (const c of sub.commands) {
      const redirects = [...c.redirects, ...shell.redirects]
      lift.set(c, {
        ...c,
        wrappers: [...shell.wrappers, ...c.wrappers],
        wrapped: [...shell.wrapped, ...c.wrapped],
        captured: c.captured || shell.captured,
        redirects,
        stdout: c.stdout || shell.stdout,
      })
    }
    const lifted = (c: SimpleCommand) => lift.get(c) ?? c
    out.commands.push(...sub.commands.map(lifted))
    out.errors.push(...sub.errors)
    out.untilClauses.push(...sub.untilClauses.map((u) => u.map(lifted)))
    out.pipelines.push(...sub.pipelines.map((p) => p.map(lifted)))
  }
  const byNode = new Map<any, SimpleCommand>()
  const pipelines: any[] = []
  try {
    walk(ast, (n, captured, outer) => {
      if (n.type === 'Pipeline') pipelines.push({ node: n, captured })
      for (const e of n.errors ?? []) out.errors.push(`${e.message} at ${e.pos}`)
      if (n.type === 'While') {
        const clause = source.slice(n.clause.pos, n.clause.end)
        // `while ! cond` waits for cond to succeed, exactly like `until cond`
        if (n.kind === 'until' || clause.trimStart().startsWith('!')) {
          const sub = analyze(clause, depth + 1)
          out.untilClauses.push(sub.commands)
          out.errors.push(...sub.errors)
        }
      }
      if (n.type !== 'Command' || !n.name) return
      let { words, wrappers, wrapped } = unwrap([n.name.value, ...n.args.map(argText)])
      // A wrapper with nothing to run (`sudo -v`) is itself the command
      if (!words.length) {
        const last = wrappers.pop()
        const call = wrapped.pop()
        if (!last || !call) return
        words = call
      }
      const prog = words[0]!
      const name = basename(prog)
      const args = words.slice(1)
      const own: Redirection[] = n.redirects.map(redirection)
      const stdout = [own, ...outer].map(stdoutOf).find((s) => s) ?? ''
      const cmd: SimpleCommand = { name, prog, args, wrappers, wrapped, captured, redirects: [...own, ...outer.flat()], stdout }
      out.commands.push(cmd)
      byNode.set(n, cmd)

      // Re-parse script strings handed to another shell
      if (SHELLS.has(name)) {
        const c = args.findIndex((a) => /^-[a-zA-Z]*c[a-zA-Z]*$/.test(a))
        const script = args[c + 1]
        if (c >= 0 && script !== undefined) nested(script, cmd)
      } else if (name === 'eval') {
        nested(args.join(' '), cmd)
      }
    })
    for (const { node, captured } of pipelines)
      out.pipelines.push(
        node.commands.map(
          (c: any, i: number): SimpleCommand =>
            byNode.get(c) ?? { name: '', prog: '', args: [], wrappers: [], wrapped: [], captured: captured || i < node.commands.length - 1, redirects: [], stdout: '' },
        ),
      )
  } catch (err) {
    // A walk that dies midway has not seen every command
    out.errors.push(`analysis failed: ${(err as Error)?.message ?? err}`)
  }
  return out
}

export const simpleCommands = (source: string): SimpleCommand[] => analyze(source).commands

files.hooks/builtin-rules.ts:
// The built-in rules, written in the same rule-file format as custom rules (see
// README.md) and compiled by the same engine. Each is toggled by the userConfig
// option named after its id (find-xdev -> find_xdev). This is a .ts module only
// because a hooks module can import nothing but code files.
import type { RuleFile } from './engine.ts'

// CEL fragments shared by the rules that point to the Read, Write and Edit tools.
// Each takes the CEL expression for a Cmd (or for a list of file operands).

// Its output reaches the tool result: not piped, substituted or redirected
const toTerminal = (c: string) => `!${c}.captured && ${c}.stdout == ''`
// It runs as the user, not behind sudo, run0 or doas (directly or through `sudo sh -c`),
// so the file tools can reach the files it does
const unelevated = (c: string) => `!${c}.wrappers.exists(w, w in ELEVATE)`
// Operands that are regular files the file tools can open
const someFiles = (f: string) => `size(${f}) > 0 && ${f}.all(x, x != '-' && !x.matches(SPECIAL_FILE))`
const noFiles = (f: string) => `size(${f}) == 0`
// cat that only shows files (or the one its stdin is redirected from), at most numbering lines
const catShows = (c: string) =>
  `${c}.name == 'cat' && ${unelevated(c)} && ${c}.args.opts(CAT).all(o, o in ['b', 'n', 's', 'u']) && cel.bind(f, ${c}.args.operands(CAT), size(f) > 0 ? ${someFiles('f')} : ${c}.redirects.exists(r, r.op == '<' && r.fd <= 0 && !r.target.matches(SPECIAL_FILE)))`
// head or tail picking lines (not bytes, not following)
const headPicks = (c: string, names: string, files: (f: string) => string) =>
  `${c}.name in ${names} && ${c}.args.opts(HEAD_TAIL).all(o, o in ['n', 'q', 'v'] || o.matches('^[0-9]$')) && cel.bind(f, ${c}.args.operands(HEAD_TAIL), ${files('f')})`
// sed -n 'X,Yp', sed 'X,Y!d' or sed 'Nq': the script from -e, or else the first operand.
// Not with -z, whose "lines" are NUL-separated records
const sedPicks = (c: string, files: (f: string) => string) =>
  `${c}.name == 'sed' && cel.bind(o, ${c}.args.opts(SED), !('i' in o) && !('f' in o) && !('z' in o) && cel.bind(e, ${c}.args.optValues(SED, 'e'), cel.bind(ops, ${c}.args.operands(SED), cel.bind(scripts, size(e) > 0 ? e : ops.take(1), size(scripts) > 0 && scripts.all(s, s.matches('n' in o ? SED_PRINT : SED_KEEP)) && cel.bind(f, size(e) > 0 ? ops : ops.drop(1), ${files('f')})))))`
// awk 'NR>=X && NR<=Y': the program is the first operand; var=value operands are not files
const awkPicks = (c: string, files: (f: string) => string) =>
  `${c}.name in AWKS && cel.bind(o, ${c}.args.opts(AWK), !('f' in o) && !('e' in o) && cel.bind(ops, ${c}.args.operands(AWK), size(ops) > 0 && ops[0].matches(AWK_LINES) && cel.bind(f, ops.drop(1).filter(x, !x.matches('^[A-Za-z_][A-Za-z0-9_]*=')), ${files('f')})))`
// Its stdin is a heredoc or here-string of fixed text (nothing for the shell to expand)
const literalStdin = (c: string) =>
  `${c}.redirects.exists(r, r.op in ['<<', '<<-', '<<<'] && r.fd <= 0 && (r.quoted || !r.body.matches(EXPANSION)))`
const catFromLiteral = (c: string) => `${c}.name == 'cat' && ${c}.args.operands(CAT).all(x, x == '-') && ${literalStdin(c)}`
const teeFiles = (c: string) => `${c}.name == 'tee' && ${unelevated(c)} && cel.bind(f, ${c}.args.operands(TEE), size(f) > 0 && f.all(x, !x.matches(SPECIAL_FILE)))`
// A Python script, from -c or from a heredoc on stdin, that matches every regex in PY_EDIT
const pyEdits = (s: string) => `PY_EDIT.all(re, ${s}.matches(re))`
const pythonEdits = (c: string) =>
  `${c}.name.matches(PYTHON_NAME) && ${unelevated(c)} && cel.bind(o, ${c}.args.opts(PYTHON), ${c}.args.optValues(PYTHON, 'c').exists(s, ${pyEdits('s')}) || !('c' in o) && !('m' in o) && cel.bind(ops, ${c}.args.operands(PYTHON), size(ops) == 0 || ops[0] == '-') && ${c}.redirects.exists(r, r.op in ['<<', '<<-', '<<<'] && r.fd <= 0 && ${pyEdits('r.body')}))`

export const builtinRules: RuleFile = {
  defs: {
    // find's leading options (-H -L -P, -D <debugopts>, -O<level>); its start points follow
    FIND_LEAD: { short: 'HLPD:O:', posix: true },
    // find's expression: primaries that consume a value, which may itself look like an option
    FIND_EXPR: {
      words: {
        '-D': 1,
        '-name': 1, '-iname': 1, '-path': 1, '-ipath': 1, '-wholename': 1, '-iwholename': 1, '-regex': 1, '-iregex': 1,
        '-lname': 1, '-ilname': 1, '-type': 1, '-xtype': 1, '-user': 1, '-group': 1, '-perm': 1, '-size': 1,
        '-newer': 1, '-anewer': 1, '-cnewer': 1, '-samefile': 1, '-mtime': 1, '-atime': 1, '-ctime': 1, '-mmin': 1,
        '-amin': 1, '-cmin': 1, '-links': 1, '-inum': 1, '-uid': 1, '-gid': 1, '-used': 1, '-fstype': 1, '-printf': 1,
        '-fprintf': 1, '-fprint': 1, '-fprint0': 1, '-fls': 1, '-context': 1, '-maxdepth': 1, '-mindepth': 1, '-newerXY': 1,
        '-exec': [';', '+'], '-execdir': [';', '+'], '-ok': [';', '+'], '-okdir': [';', '+'],
      },
      wordPatterns: { '^-newer[aBcmt][aBcmt]$': 1 },
    },
    // BSD/macOS find's leading flags (-E -H -L -P -X -d -s -x) with -x, its spelling of -xdev
    FIND_BSD_XDEV: '^-[EHLPXdsx]*x[EHLPXdsx]*$',
    // GNU find's informational primaries: find prints and exits, searching nothing
    FIND_INFO: ['-help', '--help', '-version', '--version'],
    // pgrep/pkill options that take a value, so in `-uf` the f is a user name, not -f
    PGREP: { short: 'dFgGJOPrstTuU', shortTakesValue: true, long: { full: 'f', 'list-full': 'a' } },
    GREPS: ['grep', 'egrep', 'fgrep', 'rg'],
    // Files the Read, Write and Edit tools are not for
    SPECIAL_FILE: '^/(dev|proc|sys)/',
    // Wrappers that run a command as another user, whose files the file tools may not reach
    ELEVATE: ['sudo', 'run0', 'doas'],
    // Text the shell would expand in an unquoted heredoc
    EXPANSION: '[$`]',
    // cat's options; with nothing but -b -n -s -u it only shows the file
    CAT: {
      short: 'AbeEnstTuv',
      long: { 'show-all': 'A', 'number-nonblank': 'b', 'show-ends': 'E', number: 'n', 'squeeze-blank': 's', 'show-tabs': 'T', 'show-nonprinting': 'v' },
    },
    HEAD_TAIL: {
      short: 'c:n:s:fFqvz',
      long: {
        bytes: 'c:', lines: 'n:', 'sleep-interval': 's:', pid: 'pid:', 'max-unchanged-stats': 'max-unchanged-stats:',
        follow: 'f', quiet: 'q', silent: 'q', verbose: 'v', 'zero-terminated': 'z',
      },
    },
    // GNU sed; -i takes an optional suffix in the same argument (-i.bak)
    SED: {
      short: 'nrEsuzi::e:f:l:',
      long: {
        quiet: 'n', silent: 'n', 'in-place': 'i', expression: 'e:', file: 'f:', 'line-length': 'l:',
        'regexp-extended': 'E', separate: 's', unbuffered: 'u', 'null-data': 'z',
      },
    },
    // A sed -n script that prints a line or a range of lines (X,Y X,$ X,+N), maybe quitting after
    SED_PRINT: String.raw`^\s*(\d+|\$)(\s*,\s*(\d+|\$|\+\d+))?\s*p\s*(;\s*\d+\s*q\s*)?;?\s*$`,
    // A sed script (without -n) that keeps only a range of lines: X,Y!d or Nq
    SED_KEEP: String.raw`^\s*((\d+|\$)(\s*,\s*(\d+|\$|\+\d+))?\s*!\s*d|\d+\s*q)\s*;?\s*$`,
    // A sed script of nothing but s commands (on every line, or on a line or range; g included,
    // since Edit's replace_all does the same) and deletions of a line or range, separated by ; or newlines
    SED_EDIT: String.raw`^[\s;]*(?:(?:(?:(?:\d+|\$)(?:[ \t]*,[ \t]*(?:\d+|\$))?[ \t]*)?s([^\\\n\sA-Za-z0-9])(?:\\.|(?!\1)[^\\\n])*\1(?:\\.|(?!\1)[^\\\n])*\1[0-9gpIiMm]*|(?:\d+|\$)(?:[ \t]*,[ \t]*(?:\d+|\$))?[ \t]*d)[ \t]*(?:[;\n][\s;]*|$))+$`,
    AWKS: ['awk', 'gawk', 'mawk', 'nawk'],
    AWK: { short: 'F:v:f:e:', long: { 'field-separator': 'F:', assign: 'v:', file: 'f:', source: 'e:' }, posix: true },
    // An awk program that prints a line or a range of lines by NR (or FNR), maybe exiting after
    AWK_LINES: String.raw`^\s*F?NR\s*(==|>=|<=|>|<)\s*\d+\s*((&&|,)\s*F?NR\s*(==|>=|<=|>|<)\s*\d+\s*)?(\{\s*(print(\s+\$0)?\s*;?\s*)?(exit\s*;?\s*)?\}\s*)?$`,
    TEE: { short: 'aip', long: { append: 'a', 'ignore-interrupts': 'i' } },
    PYTHON_NAME: String.raw`^python(3(\.\d+)?)?$`,
    // Options stop at the first operand: the script file, or - for stdin
    PYTHON: { short: 'bBdEhiIOPqsSuvVxc:m:W:X:', posix: true },
    // A Python script that edits a file: it imports re or calls .replace(), opens a file
    // (open() or pathlib), writes (.write(), .write_text(), .write_bytes() or .writelines()) and has a
    // multiline (triple-quoted) string literal. It must match all four.
    PY_EDIT: [
      String.raw`(^|[\n;])[ \t]*(import[ \t]+([\w.]+([ \t]+as[ \t]+\w+)?[ \t]*,[ \t]*)*re(?![\w.])|from[ \t]+re[ \t]+import\b)|\.replace\s*\(`,
      String.raw`\bopen\s*\(|\bpathlib\b`,
      String.raw`\.write(_text|_bytes|lines)?\s*\(`,
      `"{3}|'{3}`,
    ],
  },
  rules: [
    {
      id: 'monitor-disabled',
      tools: ['Monitor'],
      when: 'true',
      deny: 'Monitor is disabled. Use Bash with run_in_background to spawn a blocking waiter that exits on the next event.',
    },
    {
      // A ws source streams a WebSocket and runs no shell, so there is nothing to check.
      // With neither field the shell rules would be checking an empty string: fail closed.
      id: 'monitor-no-command',
      tools: ['Monitor'],
      when: '!(has(input.command) && type(input.command) == string) && !has(input.ws)',
      deny: 'Monitor call should have either a command or a ws source.',
    },
    {
      // First among the shell rules: if the command can't be parsed, the rules below can't be trusted to see all of it
      id: 'malformed-bash',
      when: 'size(errors) > 0',
      deny: 'Malformed bash command ({{ errors[0] }}). Fix the syntax and retry.',
    },
    {
      // `/*` expands to every top-level entry, which scans the whole filesystem too
      id: 'find-root',
      when: "cmds.exists(c, c.name == 'find' && c.args.operands(FIND_LEAD).takeWhile(r'^(?!-|[(!]$)').exists(p, p.matches(r'^/+(\\./?)*\\*?$')))",
      deny: 'find rooted at / is disabled. Scan a specific directory instead.',
    },
    {
      // -mount is the traditional spelling of -xdev, -x the BSD one; --help and --version search nothing
      id: 'find-xdev',
      when: "cmds.exists(c, c.name == 'find' && !c.args.opts(FIND_EXPR).exists(o, o in ['-xdev', '-mount'] || o.matches(FIND_BSD_XDEV) || o in FIND_INFO))",
      deny: 'find must specify -xdev so it does not cross filesystem boundaries. To search several filesystems, issue a separate find -xdev per filesystem.',
    },
    {
      // pkill has no list-full option, so -a does not help it
      id: 'pgrep-f',
      when: "cmds.exists(c, cel.bind(o, c.args.opts(PGREP), 'f' in o && (c.name == 'pkill' || c.name == 'pgrep' && !('a' in o))))",
      deny: 'pgrep -f and pkill -f can match helper processes spawned by the harness, and pkill would kill them. Use pgrep -af and confirm each match cmdline by yourself.',
    },
    {
      id: 'pgrep-captured',
      when: "cmds.exists(c, c.name == 'pgrep' && c.captured)",
      deny: 'Do not capture pgrep output in a pipe or substitution ($(...), `...`, <(...)). Let pgrep print straight to stdout and read the result.',
    },
    {
      id: 'until-grep',
      when: 'untilConds.exists(cond, cond.exists(c, c.name in GREPS))',
      deny: 'An "until grep ..." (or "while ! grep ...") loop never exits if the process writing the log silently dies. Watch the process instead: tail -f --pid=<PID> <log> | grep -m1 <pattern> (tail stops when the process exits, ending the pipeline either way).',
    },
    {
      id: 'sudo',
